package policy; import core.PortRange;import core.StringUtil; public final class NftablesParser{public FirewallRule parseLine(String line){String s=StringUtil.stripComment(line).trim();if(s.isEmpty())return null;String[] t=s.split("\s+");FirewallRule r=new FirewallRule();for(int i=0;i<t.length;i++){String x=t[i].toLowerCase();if(x.equals("chain")&&i+1<t.length)r.chain(t[++i].toUpperCase());else if(x.equals("ip")&&i+2<t.length&&t[i+1].equals("saddr"))r.source(t[i+=2]);else if(x.equals("ip")&&i+2<t.length&&t[i+1].equals("daddr"))r.destination(t[i+=2]);else if((x.equals("tcp")||x.equals("udp"))&&i+2<t.length){r.protocol(x);if(t[i+1].equals("dport"))r.destinationPort(PortRange.parse(t[i+=2]));else if(t[i+1].equals("sport"))r.sourcePort(PortRange.parse(t[i+=2]));}else if(x.matches("accept|drop|reject"))r.action(x.toUpperCase());}return r;}}
